import{_ as t,o as a,c as n,a9 as o}from"./chunks/framework.AY-u9rel.js";const p=JSON.parse(`{"title":"Introduction to Feluqa","description":"A short introduction to Feluqa, its purpose, and the guides that explain its product model, vocabulary, and architecture.","frontmatter":{"requestedLanguage":"fr","contentLanguage":"en","languageFallbackNotice":"Cette page n’est pas disponible en Français. La version en anglais est affichée.","sidebarTitle":"Introduction","icon":"book-open","title":"Introduction to Feluqa","description":"A short introduction to Feluqa, its purpose, and the guides that explain its product model, vocabulary, and architecture.","summary":"Introduces Feluqa's goals for Rust applications across web, desktop, mobile, IoT, workstation, and high-stakes environments. It explains that the platform is under development, distinguishes existing foundations from design targets, and directs readers to product, architecture, security, and deployment guides.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":1,"status":"Exploring","tags":["feluqa","about","rust","introduction"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"},"search":false},"headers":[],"relativePath":"fr/get-started/index.md","filePath":"fr/get-started/index.md"}`),r={name:"fr/get-started/index.md"};function i(s,e,d,l,u,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction-to-feluqa" tabindex="-1">Introduction to Feluqa <a class="header-anchor" href="#introduction-to-feluqa" aria-label="Permalink to &quot;Introduction to Feluqa&quot;">​</a></h1><p>Feluqa is an application platform and runtime built with Rust for <strong>enterprise backends, standalone workstations, high-stakes operations, tactical units, and defense-adjacent workloads</strong> <em>(such as ground-side drone telemetry, sensor-fusion ingestion, and secure logistics)</em>.</p><p>The goal is to share one codebase across web, desktop, mobile, and IoT deployments, while adapting each build to its target environment.</p><p>By avoiding heavy runtime overhead and garbage-collection pauses, Feluqa aims to bring the performance and control of native software to business applications and field systems.</p><p>Feluqa is under development. Some capabilities are implemented; others described here are design targets. Each guide marks its implementation status so readers can tell the difference.</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Implemented</strong></td><td>Available in the current Feluqa release and covered by the documented baseline.</td></tr><tr><td><strong>Partial</strong></td><td>Some foundations exist, and the page identifies what is missing.</td></tr><tr><td><strong>Target</strong></td><td>An agreed design that is not yet fully implemented.</td></tr><tr><td><strong>Exploring</strong></td><td>An idea or working proposal that may change.</td></tr></tbody></table><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ul><li><a href="/fr/get-started/introduction/product-and-audience">Product and audience</a>: understand the product model, the people who interact with Feluqa, and what the platform provides.</li><li><a href="/fr/get-started/introduction/taxonomy">Taxonomy</a>: learn the shared meanings of Application, Platform, developer kit (SDK), module, product, and other terms.</li><li><a href="/fr/get-started/introduction/architecture-overview">Architecture overview</a>: see how source code, modules, build artifacts, runtime components, and deployment targets fit together.</li><li><a href="/fr/learn/create-your-first-application">Create your first application</a>: see the planned path from project setup to a useful running application.</li></ul><h2 id="continue-reading" tabindex="-1">Continue reading <a class="header-anchor" href="#continue-reading" aria-label="Permalink to &quot;Continue reading&quot;">​</a></h2><ul><li><a href="/fr/security/authorization-model">Security model</a>: explore authorization and isolation.</li><li><a href="/fr/deployment/installing-an-app-with-the-cli">Install an app on a new server</a>: follow the deployment workflow.</li></ul>',10)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
